from decimal import ROUND_DOWN, Decimal

CENT = Decimal("0.01")


def to_cents(amount: Decimal) -> int:
    return int((amount / CENT).to_integral_value())


def split(amount: Decimal, parts: int) -> list[Decimal]:
    if parts < 1:
        raise ValueError("parts must be at least 1")
    share = (amount / parts).quantize(CENT, rounding=ROUND_DOWN)
    return [share] * parts

from dataclasses import dataclass, field
from decimal import Decimal


@dataclass
class Ledger:
    entries: list[tuple[str, Decimal]] = field(default_factory=list)

    def post(self, account: str, amount: Decimal) -> None:
        self.entries.append((account, amount))

    def balance(self, account: str) -> Decimal:
        return sum((a for name, a in self.entries if name == account), Decimal(0))
